bsnGlobalDot11bLongRetryLimit = MibScalar((1, 3, 6, 1, 4, 1, 14179, 2, 3, 2, 2, 13), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 255))).setMaxAccess("readonly")
