bsnGlobalDot11aMaxReceiveLifetime = MibScalar((1, 3, 6, 1, 4, 1, 14179, 2, 3, 3, 2, 16), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(1, 4294967295))).setMaxAccess("readonly")
